-- Booking foundations. Generated by drizzle-kit, then edited by hand (the
-- order matters; every hand edit is marked "manual"):
--   1. venue.timezone: manual order (nullable column -> backfill from the UF
--      -> NOT NULL -> CHECK), drizzle emitted a plain NOT NULL column.
--   2. venue_hours: manual order (add id, drop the composite PK, new PK) and a
--      named PK; drizzle emitted an inline PRIMARY KEY after the DROP.
--   3. manual: legacy price_rule / availability_block rows are normalized or
--      removed before the CHECKs, and the migration fails loudly if any remain.
--   4. manual: the EXCLUDE constraint (drizzle cannot express it).

-- 1. venue.timezone (IANA). The CASE mirrors defaultTimezoneForUf in
-- @arenaz/contracts (a contracts test parses this migration to keep both in sync).
ALTER TABLE "venue" ADD COLUMN "timezone" text;--> statement-breakpoint
UPDATE "venue" SET "timezone" = CASE
  WHEN "state" IN ('AC') THEN 'America/Rio_Branco'
  WHEN "state" IN ('AM') THEN 'America/Manaus'
  WHEN "state" IN ('RR') THEN 'America/Boa_Vista'
  WHEN "state" IN ('RO') THEN 'America/Porto_Velho'
  WHEN "state" IN ('MT') THEN 'America/Cuiaba'
  WHEN "state" IN ('MS') THEN 'America/Campo_Grande'
  WHEN "state" IN ('PA', 'AP') THEN 'America/Belem'
  WHEN "state" IN ('TO') THEN 'America/Araguaina'
  WHEN "state" IN ('MA', 'PI', 'CE', 'RN', 'PB') THEN 'America/Fortaleza'
  WHEN "state" IN ('PE') THEN 'America/Recife'
  WHEN "state" IN ('AL', 'SE') THEN 'America/Maceio'
  WHEN "state" IN ('BA') THEN 'America/Bahia'
  ELSE 'America/Sao_Paulo'
END;--> statement-breakpoint
ALTER TABLE "venue" ALTER COLUMN "timezone" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "venue" ADD CONSTRAINT "venue_timezone_check" CHECK ("venue"."timezone" in ('America/Sao_Paulo', 'America/Bahia', 'America/Fortaleza', 'America/Recife', 'America/Maceio', 'America/Belem', 'America/Araguaina', 'America/Manaus', 'America/Boa_Vista', 'America/Porto_Velho', 'America/Cuiaba', 'America/Campo_Grande', 'America/Rio_Branco', 'America/Noronha', 'America/Santarem', 'America/Eirunepe'));--> statement-breakpoint

-- 2. venue_hours: several intervals per weekday, so the (venue_id, weekday)
-- primary key becomes a surrogate id (existing rows get one each).
ALTER TABLE "venue_hours" ADD COLUMN "id" uuid DEFAULT gen_random_uuid() NOT NULL;--> statement-breakpoint
ALTER TABLE "venue_hours" DROP CONSTRAINT "venue_hours_venue_id_weekday_pk";--> statement-breakpoint
ALTER TABLE "venue_hours" ADD CONSTRAINT "venue_hours_pkey" PRIMARY KEY ("id");--> statement-breakpoint
CREATE INDEX "venue_hours_venue_id_weekday_idx" ON "venue_hours" USING btree ("venue_id","weekday");--> statement-breakpoint

-- 3a. price_rule: the API never accepted these rows, so they can only come from
-- manual edits. Invalid weekdays are dropped from the array; a rule whose
-- minutes or price are out of bounds (or whose weekdays end up empty) cannot be
-- repaired without guessing, so it is removed.
UPDATE "price_rule" SET "weekdays" = (
  SELECT coalesce(array_agg(d ORDER BY d), '{}'::smallint[])
    FROM (SELECT DISTINCT d FROM unnest("price_rule"."weekdays") AS d WHERE d BETWEEN 0 AND 6) valid
)
WHERE NOT (cardinality("weekdays") > 0 AND "weekdays" <@ ARRAY[0, 1, 2, 3, 4, 5, 6]::smallint[]);--> statement-breakpoint
DELETE FROM "price_rule"
WHERE cardinality("weekdays") = 0
   OR "start_minute" < 0 OR "end_minute" > 1440
   OR "start_minute" % 30 <> 0 OR "end_minute" % 30 <> 0
   OR "price_cents_per_hour" > 1000000;--> statement-breakpoint

-- 3b. availability_block: a finite range with other bounds becomes [start, end);
-- an infinite one is removed; of two overlapping blocks of a court the one
-- created later is removed (repeated until none overlap).
UPDATE "availability_block" SET "period" = tstzrange(lower("period"), upper("period"), '[)')
WHERE NOT lower_inf("period") AND NOT upper_inf("period")
  AND NOT (lower_inc("period") AND NOT upper_inc("period"));--> statement-breakpoint
DELETE FROM "availability_block" WHERE lower_inf("period") OR upper_inf("period");--> statement-breakpoint
DO $$
DECLARE
  clash uuid;
BEGIN
  LOOP
    SELECT b."id" INTO clash
      FROM "availability_block" a
      JOIN "availability_block" b ON a."field_id" = b."field_id" AND a."id" <> b."id" AND a."period" && b."period"
     WHERE (a."created_at", a."id") < (b."created_at", b."id")
     LIMIT 1;
    EXIT WHEN clash IS NULL;
    DELETE FROM "availability_block" WHERE "id" = clash;
  END LOOP;
END $$;--> statement-breakpoint

-- 3c. Fail loudly (before the constraints, with a readable message) if any
-- violating row survived.
DO $$
DECLARE
  bad integer;
BEGIN
  SELECT count(*) INTO bad FROM "price_rule"
   WHERE "start_minute" < 0 OR "end_minute" > 1440
      OR "start_minute" % 30 <> 0 OR "end_minute" % 30 <> 0
      OR cardinality("weekdays") = 0
      OR NOT ("weekdays" <@ ARRAY[0, 1, 2, 3, 4, 5, 6]::smallint[])
      OR "price_cents_per_hour" > 1000000;
  IF bad > 0 THEN
    RAISE EXCEPTION 'migration 0006: % price_rule row(s) still violate the new CHECKs', bad;
  END IF;
  SELECT count(*) INTO bad FROM "availability_block"
   WHERE NOT (lower_inc("period") AND NOT upper_inc("period") AND NOT lower_inf("period") AND NOT upper_inf("period"));
  IF bad > 0 THEN
    RAISE EXCEPTION 'migration 0006: % availability_block row(s) still violate the bounds CHECK', bad;
  END IF;
END $$;--> statement-breakpoint

-- 4. The CHECKs (as generated) ...
ALTER TABLE "availability_block" ADD CONSTRAINT "availability_block_bounds_check" CHECK (lower_inc("availability_block"."period") and not upper_inc("availability_block"."period") and not lower_inf("availability_block"."period") and not upper_inf("availability_block"."period"));--> statement-breakpoint
ALTER TABLE "price_rule" ADD CONSTRAINT "price_rule_bounds_check" CHECK ("price_rule"."start_minute" >= 0 and "price_rule"."end_minute" <= 1440 and "price_rule"."start_minute" % 30 = 0 and "price_rule"."end_minute" % 30 = 0);--> statement-breakpoint
ALTER TABLE "price_rule" ADD CONSTRAINT "price_rule_weekdays_check" CHECK (cardinality("price_rule"."weekdays") > 0 and "price_rule"."weekdays" <@ array[0, 1, 2, 3, 4, 5, 6]::smallint[]);--> statement-breakpoint
ALTER TABLE "price_rule" ADD CONSTRAINT "price_rule_price_max_check" CHECK ("price_rule"."price_cents_per_hour" <= 1000000);--> statement-breakpoint

-- ... and the EXCLUDE (manual): no two blocks overlap on the same court
-- (btree_gist is installed by migration 0000). The service keeps its own
-- check under the field lock; this is the safety net (23P01).
ALTER TABLE "availability_block" ADD CONSTRAINT "availability_block_no_overlap" EXCLUDE USING gist ("field_id" WITH =, "period" WITH &&);
